import re






MAX_SCAN = 3700

ONE_DAY = datetime.timedelta(days=1)
DAY_RE = re.compile(r"^\s*(\d{4})-(\d{2})-(\d{2})")



def parse_day(text):

    match = DAY_RE.match(str(text or ""))
    if not match:
