        if len(first) == 4:
            return iso(int(first), int(second), int(third))
        if len(third) != 4:
            return None
        if order == "MDY":
            return iso(int(third), int(first), int(second))
        return iso(int(third), int(second), int(first))
    words = words_of(text)
    months = [MONTHS[w] for w in words if w in MONTHS]
    if len(months) != 1:
